using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change #1: Discriminator property renamed from
        // "Discriminator" to "$type". Existing 500K documents use "Discriminator",
        // and direct SQL queries reference c.Discriminator — keep the old name.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // EF Core 9 breaking change #2: Id format changed from "EntityType|Key"
        // to just "Key". Existing documents use "Product|123" format — preserve it.
        modelBuilder.Entity<Product>().HasIdProperty(p => p.Id)
            .HasIdValueGenerationStrategy(CosmosIdValueGenerationStrategy.EntityTypePrefixed);

        // EF Core 9 breaking change #3: HasIndex is no longer silently ignored
        // on the Cosmos provider — it now throws. Removed the unsupported call.

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

